/**
 * Test that a builder with all values set yields like values in the constructed configuration.
 */
@Test
void testBuilder() {
    final StatementConfiguration.Builder builder = new StatementConfiguration.Builder().fetchDirection(1).fetchSize(2).maxFieldSize(3).maxRows(4).queryTimeout(5);
    final StatementConfiguration config = builder.build();
    assertTrue(config.isFetchDirectionSet());
    assertEquals(Integer.valueOf(1), config.getFetchDirection());
    assertTrue(config.isFetchSizeSet());
    assertEquals(Integer.valueOf(2), config.getFetchSize());
    assertTrue(config.isMaxFieldSizeSet());
    assertEquals(Integer.valueOf(3), config.getMaxFieldSize());
    assertTrue(config.isMaxRowsSet());
    assertEquals(Integer.valueOf(4), config.getMaxRows());
    assertTrue(config.isQueryTimeoutSet());
    assertEquals(Integer.valueOf(5), config.getQueryTimeout());
    assertTrue(config.isQueryTimeoutSet());
    assertEquals(Duration.ofSeconds(5), config.getQueryTimeoutDuration());
    final StatementConfiguration config2 = builder.queryTimeout(Duration.ofSeconds(3)).build();
    assertTrue(config2.isQueryTimeoutSet());
    assertEquals(Integer.valueOf(3), config2.getQueryTimeout());
    assertTrue(config2.isQueryTimeoutSet());
    assertEquals(Duration.ofSeconds(3), config2.getQueryTimeoutDuration());
}

